mapper.select:
        SELECT PRCDOC_NO, CNT||'' CNT FROM (
			SELECT ROW_NUMBER() OVER (ORDER BY CNT DESC) AS LISTNUM,
			   PRCDOC_NO, CNT FROM (
					SELECT B.PRCDOC_NO, count(*) CNT FROM GE_MP_CHECK_S A, GE_MP_PRCDOC_M B
					 WHERE A.FRM_UNQ_KY_VAL = B.FRM_UNQ_KY_VAL
					   AND B.PRCDOC_CFY = #{PRCDOC_CFY}
					 GROUP BY B.PRCDOC_NO
				) 
				ORDER BY CNT DESC
		)
